const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Asir region in Saudi Arabia (approximate center)
  const asir = ee.Geometry.Point([42.5, 18.2]).buffer(50000); // 50km buffer

  // 2. Data Acquisition using MODIS NDVI
  const modis = ee.ImageCollection('MODIS/006/MOD13A2')
    .select('NDVI')
    .filterBounds(asir);

  // Long-term period: June 2003-2011
  const longTermCol = modis
    .filter(ee.Filter.calendarRange(2003, 2011, 'year'))
    .filter(ee.Filter.calendarRange(6, 6, 'month'));

  // Recent period: June 2016-2017
  const recentCol = modis
    .filter(ee.Filter.calendarRange(2016, 2017, 'year'))
    .filter(ee.Filter.calendarRange(6, 6, 'month'));

  const longTermSize = longTermCol.size().getInfo();
  const recentSize = recentCol.size().getInfo();

  console.log(`Long-term images (2003-2011): ${longTermSize}`);
  console.log(`Recent images (2016-2017): ${recentSize}`);

  if (longTermSize === 0 || recentSize === 0) {
    console.log("Missing data for one or both periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean NDVI
  const longTermMean = longTermCol.mean().multiply(0.0001); // MODIS NDVI scale factor
  const recentMean = recentCol.mean().multiply(0.0001);

  // 4. Calculate statistics
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const longTermStats = longTermMean.reduceRegion({
    reducer: reducer,
    geometry: asir,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const recentStats = recentMean.reduceRegion({
    reducer: reducer,
    geometry: asir,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const longTermNDVI = longTermStats.NDVI_mean;
  const longTermCount = longTermStats.NDVI_count;
  const recentNDVI = recentStats.NDVI_mean;
  const recentCount = recentStats.NDVI_count;

  console.log(`Long-term (2003-2011) NDVI: ${longTermNDVI?.toFixed(4)}, Pixels: ${longTermCount}`);
  console.log(`Recent (2016-2017) NDVI: ${recentNDVI?.toFixed(4)}, Pixels: ${recentCount}`);

  // 5. Validation & Final Answer
  if (longTermCount === 0 || recentCount === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (longTermNDVI == null || recentNDVI == null || 
      isNaN(longTermNDVI) || isNaN(recentNDVI) ||
      longTermNDVI < -1 || longTermNDVI > 1 ||
      recentNDVI < -1 || recentNDVI > 1) {
    console.log("Invalid NDVI calculation.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (recentNDVI > longTermNDVI) {
    console.log(`Higher NDVI in 2016-2017 (${recentNDVI.toFixed(4)}) vs 2003-2011 (${longTermNDVI.toFixed(4)})`);
    console.log("<answer>A</answer>");
  } else {
    console.log(`Not higher: 2016-2017 (${recentNDVI.toFixed(4)}) vs 2003-2011 (${longTermNDVI.toFixed(4)})`);
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
